12	} from '@mantine/core';
13	import { useForm } from '@mantine/form';
14	import { notifications } from '@mantine/notifications';
15	import { IconCheck, IconX } from '@tabler/icons-react';
16	import { zod4Resolver } from 'mantine-form-zod-resolver';
17	import { useRouter } from 'next/navigation';
18	import z from 'zod';
19	
20	import { PasswordFields } from '@/components/PasswordFields/PasswordFields';
21	import { authClient } from '@/lib/auth.client';
22	import { config } from '@/lib/config';
23	import { toPublicMessage, ValidationError } from '@/lib/errors';
