29	/**
30	 * Validate the password reset inputs for length and confirmation.
31	 */
32	const resetPasswordSchema = z.object({
33	    password: z.string().min(8, { message: 'Password must be at least 8 characters long' }),
34	    confirmPassword: z.string().min(1, { message: 'Please confirm your password' }),
35	}).refine((data) => data.password === data.confirmPassword, {
36	    message: 'Passwords do not match',
37	    path: ['confirmPassword'],
38	});
39	
40	/**
41	 * Render the password reset flow for a user who has a reset token.
42	 */
43	export const PasswordResetForm = ({ token }: Props) => {
44	    const router = useRouter();
45	    const form = useForm<z.infer<typeof resetPasswordSchema>>({
46	        initialValues: {
47	            password: '',
48	            confirmPassword: '',
49	        },
50	        validate: zod4Resolver(resetPasswordSchema),
51	        validateInputOnBlur: true,
52	    });
53	
54	    /**
55	     * Submit a new password for the provided reset token and surface status via notifications.
56	     */
57	    const handleSubmit = async (values: z.infer<typeof resetPasswordSchema>) => {
58	        const id = notifications.show({
59	            loading: true,
60	            title: 'Resetting password',
61	            message: 'Updating your password...',
62	            autoClose: false,
63	            withCloseButton: false,
64	        });
65	
66	        try {
67	            const { status } = await authClient.resetPassword({
68	                newPassword: values.password,
69	                token,
70	            });
71	
72	            if (!status) {
73	                throw new ValidationError('Reset password returned an unsuccessful status.', {
74	                    publicMessage: 'Unable to reset password.',
75	                    details: {
76	                        tokenPresent: Boolean(token),
77	                    },
78	                });
79	            }
80	
81	            notifications.update({
82	                id,
83	                color: 'teal',
84	                title: 'Password updated',
85	                message: 'Your password has been reset successfully.',
86	                icon: <IconCheck size={config.notificationIconSize} />,
87	                loading: false,
88	                autoClose: config.notificationAutoClose,
89	            });
90	
91	            router.push('/footy/auth/signin');
92	        } catch (error) {
93	            const message = toPublicMessage(error, 'Unable to reset password.');
94	            notifications.update({
95	                id,
96	                color: 'red',
97	                title: 'Error',
98	                message,
99	                icon: <IconX size={config.notificationIconSize} />,
100	                loading: false,
101	                autoClose: false,
102	                withCloseButton: true,
103	            });
104	        }
105	    };
106	
107	    if (!token) {
108	        return (
109	            <Notification icon={<IconX size={config.notificationIconSize} />} color="red">
110	                <Text>Password reset link is missing or invalid.</Text>
111	            </Notification>
112	        );
113	    }
114	
115	    return (
116	        <Paper w="100%" maw="35rem" p="xl">
117	            <Stack>
118	                <Title order={2} mb="xs" w="100%" ta="center">
119	                    Reset your password
120	                </Title>
121	                <Divider mb="xs" />
122	            </Stack>
123	
124	            <Box
125	                component="form"
126	                onSubmit={form.onSubmit(handleSubmit)}
127	                noValidate
128	            >
129	                <Stack>
130	                    <PasswordFields
131	                        passwordLabel="New password"
132	                        confirmPasswordLabel="Confirm new password"
133	                        passwordPlaceholder="Enter a new password"
134	                        confirmPasswordPlaceholder="Re-enter your new password"
135	                        passwordProps={form.getInputProps('password')}
136	                        confirmPasswordProps={form.getInputProps('confirmPassword')}
137	                    />
138	                    <Button type="submit" fullWidth>
139	                        Reset password
140	                    </Button>
141	                </Stack>
142	            </Box>
143	        </Paper>
144	    );
145	};
