43	export const ClaimSignup = ({ name, email, token }: Props) => {
44	    const [loading, setLoading] = useState(false);
45	    const [signupError, setSignupError] = useState<string | undefined>(undefined);
46	    const router = useRouter();
47	    const redirectPath = `/api/footy/auth/claim/${encodeURIComponent(token)}?redirect=/footy/profile`;
48	    const socialRedirect = new URL(redirectPath, getPublicBaseUrl()).toString();
49	
50	    const form = useForm({
51	        initialValues: {
52	            password: '',
53	            confirmPassword: '',
54	        },
55	        validate: zod4Resolver(ClaimSignupSchema),
56	        validateInputOnBlur: true,
57	    });
58	
59	    const handleSignUp = async (values: z.infer<typeof ClaimSignupSchema>) => {
60	        setLoading(true);
61	        setSignupError(undefined);
62	
63	        try {
64	            await authClient.signUp.email({
65	                name: name,
66	                email: email,
67	                password: values.password,
68	            }, {
69	                onError: (ctx) => {
70	                    alert(ctx.error.message);
71	                },
72	            });
73	
74	            router.push(redirectPath);
75	        } catch (err) {
76	            captureUnexpectedError(err, {
77	                layer: 'client',
78	                action: 'signUpWithEmail',
79	                component: 'ClaimSignup',
80	                route: '/claim-signup',
81	                extra: {
82	                    redirectPath,
83	                },
84	            });
85	            setSignupError('Something went wrong. Please try again.');
86	        } finally {
87	            setLoading(false);
88	        }
89	    };
90	
91	    const errorNotification = signupError ? (
92	        <Notification
93	            icon={<IconX size={config.notificationIconSize} />}
94	            color="red"
95	            onClose={() => setSignupError(undefined)}
96	        >
97	            {signupError}
98	        </Notification>
99	    ) : null;
100	
101	    return (
102	        <Container size="xs" mt="xl" >
103	            <Stack mb="lg">
104	                <Title order={2} mb="xs" w="100%" ta="center">
105	                    Finish creating your login
106	                </Title>
107	                <Text ta="center">
108	                    Your email address &quot;{email}&quot; has been verified. Choose how you want to sign in.
109	                </Text>
110	                <Divider mb="xs" />
111	                <Group justify="center" w="100%" mb="md">
112	                    <UnstyledButton
113	                        onClick={() => signInWithGoogle(socialRedirect)}
114	                        w="fit-content"
115	                        type="button"
116	                    >
117	                        <Image src="/google-signin-button-light.svg" alt="Sign in with Google" w={180} h={40} />
118	                    </UnstyledButton>
119	                    <UnstyledButton
120	                        onClick={() => signInWithMicrosoft(socialRedirect)}
121	                        w="fit-content"
122	                        type="button"
123	                    >
124	                        <Image src="/microsoft-signin-button-light.svg" alt="Sign in with Microsoft" w={215} h={41} />
125	                    </UnstyledButton>
126	                </Group>
127	                <Divider label="or" labelPosition="center" />
128	            </Stack>
129	
130	            <Box
131	                component="form"
132	                onSubmit={form.onSubmit(handleSignUp)}
133	            >
134	                <Stack>
135	                    <PasswordFields
136	                        passwordProps={form.getInputProps('password')}
137	                        confirmPasswordProps={form.getInputProps('confirmPassword')}
138	                    />
139	                    {errorNotification}
140	                    <Button
141	                        type="submit"
142	                        fullWidth
143	                        loading={loading}
144	                        disabled={!form.isValid()}
145	                    >
146	                        Create login
147	                    </Button>
148	                </Stack>
149	            </Box>
150	        </Container>
151	    );
152	};
